-- Régression : 10 -> perte 2 -> recomptage 8 -> approbation, puis rejet sans retour automatique.
BEGIN;
\ir helpers/display_loss_fixture.sql
SELECT pg_temp.authenticate_pin((SELECT uid FROM loss_actors WHERE kind='cashier'));
SET LOCAL ROLE authenticated;
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT adjust_display_stock_v5(id,8,'Physical shelf recount',gen_random_uuid()) FROM loss_products WHERE kind='main';
RESET ROLE;
SELECT pg_temp.authenticate_pin((SELECT uid FROM loss_actors WHERE kind='owner'));
SET LOCAL ROLE authenticated;
RESET ROLE;
SELECT pg_temp.authenticate_pin((SELECT uid FROM loss_actors WHERE kind='cashier'));
SET LOCAL ROLE authenticated;
