INSERT INTO loss_payload SELECT 'main',waste_display_stock_v4(id,2,'Physical display loss',key) FROM loss_products WHERE kind='main';
INSERT INTO loss_results(tap) SELECT is((SELECT value->>'status' FROM loss_payload WHERE name='main'),'pending','Loss awaits independent Owner');
INSERT INTO loss_results(tap) SELECT is((SELECT value->>'display_withdrawal_applied' FROM loss_payload WHERE name='main'),'true','Response confirms shelf withdrawal');
INSERT INTO loss_results(tap) SELECT ok(NOT ((SELECT value FROM loss_payload WHERE name='main') ?| ARRAY['current_stock','new_current_stock','new_display_stock','baseline_quantity','delta']),'Loss response contains no theoretical stock');
INSERT INTO loss_payload SELECT 'retry',waste_display_stock_v4(id,2,'Physical display loss',key) FROM loss_products WHERE kind='main';
INSERT INTO loss_results(tap) SELECT is((SELECT value->>'declaration_id' FROM loss_payload WHERE name='retry'),(SELECT value->>'declaration_id' FROM loss_payload WHERE name='main'),'Submission retry returns original declaration');
INSERT INTO loss_results(tap) SELECT throws_ok(format('SELECT waste_display_stock_v4(%L,3,%L,%L)',id,'Physical display loss',key),'22023','idempotency_conflict','Changed loss cannot reuse key') FROM loss_products WHERE kind='main';
INSERT INTO loss_results(tap) SELECT throws_ok(format('SELECT waste_display_stock_v4(NULL,2,%L,%L)','Physical display loss',key),'22023','idempotency_conflict','Null product cannot reuse key') FROM loss_products WHERE kind='main';
INSERT INTO loss_results(tap) SELECT throws_ok(format('SELECT approve_stock_declaration_v3(%L)',(SELECT value->>'declaration_id' FROM loss_payload WHERE name='main')),'P0003','owner_required','Cashier cannot approve own loss');
INSERT INTO loss_results(tap) SELECT is((SELECT quantity FROM display_stock WHERE product_id=(SELECT id FROM loss_products WHERE kind='main')),8::numeric,'Submission and retry remove shelf quantity exactly once');
INSERT INTO loss_results(tap) SELECT is((SELECT current_stock FROM products WHERE id=(SELECT id FROM loss_products WHERE kind='main')),10::numeric,'Pending loss leaves global stock unchanged');
INSERT INTO loss_results(tap) SELECT is((SELECT count(*) FROM stock_movements WHERE product_id=(SELECT id FROM loss_products WHERE kind='main')),0::bigint,'Pending loss has no global ledger effect');
INSERT INTO loss_results(tap) SELECT ok(EXISTS(SELECT 1 FROM display_movements d JOIN audit_logs a ON a.entity_id=d.id AND a.action='display.waste' WHERE d.reference_id=(SELECT (value->>'declaration_id')::uuid FROM loss_payload WHERE name='main') AND d.reference_type='stock_declaration' AND d.quantity=-2 AND d.created_by=(SELECT id FROM loss_actors WHERE kind='cashier') AND a.actor_id=d.created_by),'Shelf loss and audit reference the declarant profile');
INSERT INTO loss_payload SELECT 'approval',approve_stock_declaration_v3((SELECT (value->>'declaration_id')::uuid FROM loss_payload WHERE name='main'));
INSERT INTO loss_payload SELECT 'approval_retry',approve_stock_declaration_v3((SELECT (value->>'declaration_id')::uuid FROM loss_payload WHERE name='main'));
INSERT INTO loss_results(tap) SELECT ok((SELECT (value->>'idempotent_replay')::boolean FROM loss_payload WHERE name='approval_retry'),'Approval retry is read only');
INSERT INTO loss_results(tap) SELECT is((SELECT current_stock FROM products WHERE id=(SELECT id FROM loss_products WHERE kind='main')),8::numeric,'Owner approval removes global loss');
INSERT INTO loss_results(tap) SELECT is((SELECT quantity FROM display_stock WHERE product_id=(SELECT id FROM loss_products WHERE kind='main')),8::numeric,'Owner approval preserves recounted shelf at eight');
INSERT INTO loss_results(tap) SELECT is((SELECT count(*) FROM display_movements WHERE product_id=(SELECT id FROM loss_products WHERE kind='main')),1::bigint,'Recount no-op and approval create no second shelf movement');
INSERT INTO loss_results(tap) SELECT is((SELECT sum(quantity) FROM stock_movements WHERE product_id=(SELECT id FROM loss_products WHERE kind='main')),-2::numeric,'Global ledger contains one signed loss');
INSERT INTO loss_results(tap) SELECT ok(EXISTS(SELECT 1 FROM audit_logs WHERE entity_id=(SELECT (value->>'declaration_id')::uuid FROM loss_payload WHERE name='main') AND action='stock.declaration_approved' AND actor_id=(SELECT id FROM loss_actors WHERE kind='owner')),'Approval audit references distinct Owner profile');
INSERT INTO loss_payload SELECT 'approved_retry',waste_display_stock_v4(id,2,'Physical display loss',key) FROM loss_products WHERE kind='main';
INSERT INTO loss_results(tap) SELECT is((SELECT value->>'status' FROM loss_payload WHERE name='approved_retry'),'approved','Submission retry retains approved status');
INSERT INTO loss_payload SELECT 'rejected',waste_display_stock_v4(id,2,'Disputed physical loss',key) FROM loss_products WHERE kind='rejected';
INSERT INTO loss_payload SELECT 'reject_retry',reject_stock_declaration_v1((SELECT (value->>'declaration_id')::uuid FROM loss_payload WHERE name='rejected'),'Loss not approved');
INSERT INTO loss_results(tap) SELECT ok((SELECT (value->>'idempotent_replay')::boolean FROM loss_payload WHERE name='reject_retry'),'Rejection retry is idempotent');
INSERT INTO loss_results(tap) SELECT throws_ok(format('SELECT approve_stock_declaration_v3(%L)',(SELECT value->>'declaration_id' FROM loss_payload WHERE name='rejected')),'P0001','declaration_not_pending','Rejected loss cannot be approved later');
INSERT INTO loss_results(tap) SELECT is((SELECT current_stock FROM products WHERE id=(SELECT id FROM loss_products WHERE kind='rejected')),10::numeric,'Rejection never changes global stock');
INSERT INTO loss_results(tap) SELECT is((SELECT quantity FROM display_stock WHERE product_id=(SELECT id FROM loss_products WHERE kind='rejected')),7::numeric,'Rejection never restores shelf after later recount');
INSERT INTO loss_results(tap) SELECT is((SELECT count(*) FROM display_movements WHERE product_id=(SELECT id FROM loss_products WHERE kind='rejected')),2::bigint,'Rejection adds no compensating shelf movement');
INSERT INTO loss_payload SELECT 'rejected_retry',waste_display_stock_v4(id,2,'Disputed physical loss',key) FROM loss_products WHERE kind='rejected';
INSERT INTO loss_results(tap) SELECT is((SELECT value->>'status' FROM loss_payload WHERE name='rejected_retry'),'rejected','Original key retains rejected declaration');
INSERT INTO loss_results(tap) SELECT is((SELECT quantity FROM display_stock WHERE product_id=(SELECT id FROM loss_products WHERE kind='rejected')),7::numeric,'Rejected submission replay does not withdraw again');
INSERT INTO loss_results(tap) SELECT * FROM finish();
